- Payment Method: {{ $json.payment_method }}

Risk Assessment Rules:
1. BD phone numbers must be 11 digits starting with 013-019. Suspicious or incomplete numbers get high risk.
2. Incomplete or vague addresses (e.g. lacking house/road/area details) increase return risk.
3. High COD values (> 5000 BDT) with vague addresses get severe risk scores.

Respond strictly in valid JSON format with this exact schema:
{
  "risk_score": <number from 1 to 10>,
  "risk_level": "LOW" | "MEDIUM" | "HIGH",
  "reasons": ["<reason 1>", "<reason 2>"],
  "recommended_action": "<short recommendation>"
}",
  "stream": false
}

parameters.jsCode:
// Parse the stringified JSON response from Ollama
const rawResponse = $json.response;
let analysis = {};

try {
  analysis = JSON.parse(rawResponse);
} catch (e) {
  analysis = {
    risk_score: 5,
    risk_level: "MEDIUM",
    reasons: ["Failed to parse AI output"],
    recommended_action: "Manual Verification Required"
  };
}

// Combine original order data with risk analysis
return {
  json: {
    customer_name: $('Format Order Data').item.json.customer_name,
    phone: $('Format Order Data').item.json.phone,
    address: $('Format Order Data').item.json.address,
    order_value: $('Format Order Data').item.json.order_value,
    risk_score: analysis.risk_score || 5,
    risk_level: analysis.risk_level || "MEDIUM",
    reasons: (analysis.reasons || []).join(", "),
    recommended_action: analysis.recommended_action || "Verify with Customer"
  }
};

// Safe Order Auto-Approval Log
const data = $json;

return {
  json: {
    status: "SAFE_TO_PROCESS",
    order_status: "Approved",
    message: `Order for ${data.customer_name} (Risk Score: ${data.risk_score}/10) is safe for dispatch.`
  }
};

